/* https://crccrosbyroofing.co.uk/wp-content/plugins/wp-smart-preloader/assets/css/wsp-front-preloader.css?ver=1.15.3 */
/*--------------------------------------------------------------
 * Preloader CSS MS
 *--------------------------------------------------------------
 */

.smart-page-loader {
    display: block;
    width: 100%;
    height: 100%;
    position: fixed;
    top: 0;
    left: 0;
    background: #fefefe;
    z-index: 100000;
}

.wp-smart-loader {
    position: absolute;
    top: 50%;
    left: 50%;
    margin: -25px 0 0 -25px;
    font-size: 10px;
    z-index: 100001;
}


.wp-smart-body{
    visibility: hidden;
}


